public.bump_daily_challenge_dashboard_re.definition:
CREATE OR REPLACE FUNCTION public.bump_daily_challenge_dashboard_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid;
  v_revision bigint;
BEGIN
  -- No input changed: preserve the cursor and avoid a paid source send.
  IF TG_OP='UPDATE' AND OLD IS NOT DISTINCT FROM NEW THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'profiles' THEN
    v_user_id := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;
  ELSE
    v_user_id := NEW.user_id;
  END IF;

  -- Cascading account deletion removes the profile before child triggers run.
  -- A cursor for a deleted user is unusable and would violate the cursor FK.
  IF v_user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_user_id) THEN
    INSERT INTO public.daily_challenge_dashboard_revisions (user_id, revision, updated_at)
    VALUES (v_user_id, 1, clock_timestamp())
    ON CONFLICT (user_id) DO UPDATE
      SET revision = public.daily_challenge_dashboard_revisions.revision + 1,
          updated_at = EXCLUDED.updated_at
    RETURNING revision INTO v_revision;

    BEGIN
      PERFORM realtime.send(
        jsonb_build_object('revision', v_revision),
        'daily_mission_revision_changed',
        'daily-mission-revision:' || v_user_id::text,
        true
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Mission revision broadcast failed: %', SQLERRM;
    END;

    IF TG_TABLE_NAME = 'user_daily_challenges' THEN
      IF TG_OP = 'UPDATE'
         AND OLD.completed IS NOT TRUE
         AND NEW.completed IS TRUE THEN
        BEGIN
          PERFORM realtime.send(
            jsonb_build_object(
              'id', NEW.id,
              'challengeId', NEW.challenge_id,
              'name', NEW.challenge_name_snapshot,
              'diamondReward', NEW.diamond_reward_snapshot
            ),
            'daily_mission_completed',
            'daily-mission-completion:' || v_user_id::text,
            true
          );
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'Daily Mission completion broadcast failed: %', SQLERRM;
        END;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

public.fn_ca_diamond_prune_history(integ.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_prune_history(p_incident_days integer DEFAULT 30, p_challenge_days integer DEFAULT 400, p_abandoned_days integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_incidents integer := 0; v_challenges integer := 0; v_abandoned integer := 0;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  -- The challenge floor is 400 days and not 60, because this table is also the streak ledger:
  -- get_challenge_streak reads every completed row with no lower bound and walks back to the
  -- first gap, so deleting completed rows inside any plausible streak horizon would make a long
  -- streak uncomputable (D2). 400 days is beyond a year-long streak.
  IF p_incident_days < 7 OR p_challenge_days < 400 OR p_abandoned_days < 45 THEN
    RAISE EXCEPTION 'retention below the floor: incidents 7 days, challenges 400 days, abandoned 45 days';
  END IF;

  DELETE FROM public.ca_diamond_incidents
   WHERE resolved_at IS NOT NULL
     AND severity IN ('info', 'warning')
     AND occurred_at < now() - make_interval(days => p_incident_days);
  GET DIAGNOSTICS v_incidents = ROW_COUNT;

  DELETE FROM public.user_daily_challenges
   WHERE (claimed OR expired_at IS NOT NULL)
     AND created_at < now() - make_interval(days => p_challenge_days);
  GET DIAGNOSTICS v_challenges = ROW_COUNT;

  -- Assigned and never completed: no expiry reaches it and no claim will ever come, so it was the
  -- one class the first version could not remove even though it grows fastest (D8). Not part of
  -- any streak, because a streak counts completions.
  DELETE FROM public.user_daily_challenges
   WHERE NOT completed
     AND created_at < now() - make_interval(days => p_abandoned_days);
  GET DIAGNOSTICS v_abandoned = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'incidents_pruned', v_incidents,
                            'challenges_pruned', v_challenges, 'abandoned_pruned', v_abandoned,
                            'incident_days', p_incident_days, 'challenge_days', p_challenge_days,
                            'abandoned_days', p_abandoned_days);
END $function$

public.claim_daily_challenge_serialized_.definition:
CREATE OR REPLACE FUNCTION public.claim_daily_challenge_serialized_body(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.user_daily_challenges%ROWTYPE;
  v_new_diamonds integer;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RAISE EXCEPTION 'Cannot claim a challenge for another user' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row
  FROM public.user_daily_challenges
  WHERE id = p_challenge_row_id AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Challenge not found'; END IF;
  IF v_row.claimed THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'alreadyClaimed', true,
      'chips', 0,
      'diamonds', 0,
      'diamondBalance', (SELECT COALESCE(diamonds, 0) FROM public.profiles WHERE id = v_uid)
    );
  END IF;
  IF NOT v_row.completed THEN RAISE EXCEPTION 'Challenge not completed yet'; END IF;
  -- DIAMOND-RULINGS 3: a completed reward is claimable for seven days, for everyone. The stamp
  -- (expired_at) is what the dashboard reads; the clock is what this refuses by, so the rule
  -- holds whether or not the daily stamp has run.
  IF v_row.expired_at IS NOT NULL
     OR (v_row.completed_at IS NOT NULL AND v_row.completed_at < now() - interval '7 days') THEN
    RAISE EXCEPTION 'Challenge reward expired' USING ERRCODE = 'P0430';
  END IF;
  IF v_row.progress < v_row.requirement_snapshot THEN
    RAISE EXCEPTION 'Challenge progress %/% does not meet the assigned requirement',
      v_row.progress, v_row.requirement_snapshot;
  END IF;

  /* The optimistic-concurrency check used to compare against the CHIP snapshot,
     which is now always 0 and therefore no longer identifies anything. It reads
     the diamond snapshot - the reward the player is actually being paid - so a
     card that changed underneath the player still stops the claim. */
  IF p_reward_amount IS NOT NULL
     AND p_reward_amount IS DISTINCT FROM v_row.diamond_reward_snapshot
  THEN
    RAISE EXCEPTION 'Challenge reward changed; refresh and try again';
  END IF;

  UPDATE public.user_daily_challenges
  SET claimed = true, claimed_at = now()
  WHERE id = p_challenge_row_id;

  /* NO CHIP CREDIT. This is where `atomic_credit_wallet_and_log` stood until
     2026-09-05, paying chip_reward_snapshot into club_members.chip_balance. A
     mission reward is diamonds. Removed rather than guarded on a zeroed column,
     so a stale snapshot arriving from anywhere cannot mint a chip. */

  IF v_row.diamond_reward_snapshot > 0 THEN
    UPDATE public.profiles
    SET diamonds = COALESCE(diamonds, 0) + v_row.diamond_reward_snapshot,
        diamond_balance = COALESCE(diamonds, 0) + v_row.diamond_reward_snapshot,
        updated_at = now()
    WHERE id = v_uid
    RETURNING diamonds INTO v_new_diamonds;

    IF v_new_diamonds IS NULL THEN
      RAISE EXCEPTION 'Profile not found for user % - diamond credit failed', v_uid;
    END IF;

    INSERT INTO public.diamond_transactions (
      user_id, amount, transaction_type, type, description,
      balance_after, metadata, reference_id, created_at, counterparty, issuance_class
    ) VALUES (
      v_uid,
      v_row.diamond_reward_snapshot,
      'daily_challenge_claim',
      'daily_challenge_claim',
      'Challenge reward: ' || v_row.challenge_id,
      v_new_diamonds,
      jsonb_build_object(
        'challenge_row_id', p_challenge_row_id,
        'challenge_id', v_row.challenge_id,
        'assigned_diamond_reward', v_row.diamond_reward_snapshot
      ),
      'challenge_claim:' || p_challenge_row_id::text || ':diamonds',
      now(),
      'promo_budget:daily_challenges', 'earned'
    );
  ELSE
    SELECT COALESCE(diamonds, 0) INTO v_new_diamonds
    FROM public.profiles
    WHERE id = v_uid;
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'alreadyClaimed', false,
    'challengeId', v_row.challenge_id,
    'chips', 0,
    'diamonds', v_row.diamond_reward_snapshot,
    'diamondBalance', COALESCE(v_new_diamonds, 0)
  );
END;
$function$
